    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}
    function run(uint val1, uint val2) public {
        bool firstReverted;
        bool secondReverted;
        c.SetMinSum(val1); bool __rev0 = __ESBMC_reverted(); if (__rev0) { firstReverted = true; } else { firstReverted = false; }
        c.Initialized(); if (__ESBMC_reverted()) return;
        c.SetMinSum(val2); bool __rev1 = __ESBMC_reverted(); if (__rev1) { secondReverted = true; } else { secondReverted = false; }
        assert(!firstReverted && secondReverted);
    }
